pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 tokenId, address royaltyRecipient) public {
        // ADMISSIBLE inputs: any tokenId, any non-zero royaltyRecipient
        vm.assume(royaltyRecipient != address(0));

        // Initialize the contract through the factory-emulating initializer
        c.initialize(1, 1, "test", royaltyRecipient);

        // Ensure no specific royalty is set for tokenId (default case)
        // The fuzzer will try various tokenIds
        (address receiver, uint256 royaltyAmount) = c.getRoyalties(tokenId);

        // For the default case (no specific config), royaltyAmount must correspond to 500 BPS
        // but getRoyalties returns the configuration; we check royaltyBPS via royaltyInfo
        // royaltyInfo returns royaltyAmount = (config.royaltyBPS * salePrice) / 10000
        uint256 salePrice = 10000; // test price
        (, uint256 computedRoyalty) = c.royaltyInfo(tokenId, salePrice);

        uint256 expectedRoyalty = (500 * salePrice) / 10000; // 500 BPS default
        assertTrue(computedRoyalty == expectedRoyalty);
    }
}

